export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export type StepResult = { premium: number } | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;
const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};
const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_BASE_PREMIUM = 25;
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE_PREMIUM = 60;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

function alikeComponentsBasePremiumOf(count: number): number {
  return count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
}

// "Alike" components are components of exactly the same type.
function countAlikeComponents(components: Item[]): number[] {
  const countsByType = new Map<string, number>();
  for (const component of components) {
    countsByType.set(component.type, (countsByType.get(component.type) ?? 0) + 1);
  }
  return [...countsByType.values()];
}

function componentsBasePremiumOf(components: Item[]): number {
  return countAlikeComponents(components).reduce((sum, count) => sum + alikeComponentsBasePremiumOf(count), 0);
}

function mainItemBasePremiumOf(mainItem: Item): number {
  return MAIN_ITEM_BASE_PREMIUMS[mainItem.type];
}

function mainItemsBasePremiumOf(mainItems: Item[]): number {
  return mainItems.reduce((sum, item) => sum + mainItemBasePremiumOf(item), 0);
}

function policyBasePremiumOf(items: Item[]): number {
  const mainItems = items.filter((item) => !isComponent(item));
  const components = items.filter(isComponent);
  return mainItemsBasePremiumOf(mainItems) + componentsBasePremiumOf(components);
}

function curseSurchargeOf(item: Item): number {
  return item.cursed ? mainItemBasePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;
}

function highEnchantmentSurchargeOf(item: Item): number {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
    ? mainItemBasePremiumOf(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
    : 0;
}

function itemRiskSurchargesOf(items: Item[]): number {
  return items.reduce((sum, item) => sum + curseSurchargeOf(item) + highEnchantmentSurchargeOf(item), 0);
}

function roundPremiumInMHPCOsFavor(premium: number): number {
  return Math.ceil(premium);
}

function quotePremium(items: Item[]): number {
  const policyBasePremium = policyBasePremiumOf(items);
  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  const riskSurcharges = itemRiskSurchargesOf(items);
  return roundPremiumInMHPCOsFavor(policyBasePremium + riskSurcharges + firstInsuranceSurcharge + PROCESSING_FEE);
}

export function processScenario(scenario: Scenario): { results: StepResult[] } {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
}
import { describe, expect, it } from "vitest";
import { type Item, processScenario } from "./claim-office.js";

const newcomer = { yearsWithMHPCO: 0 };
const rune: Item = { type: "rune" };
const moonstone: Item = { type: "moonstone" };

function times(count: number, item: Item): Item[] {
  return Array.from({ length: count }, () => item);
}

function premiumFor(items: Item[], customer = newcomer): number {
  const { results } = processScenario({ customer, steps: [{ op: "quote", items }] });
  return (results[0] as { premium: number }).premium;
}

describe("quote", () => {
  it("empty item list -> premium 5 G (only the processing fee)", () => {
    expect(premiumFor([])).toBe(5);
  });
  it("newcomer insures a plain sword -> 100 base + 10 first insurance + 5 fee = 115 G", () => {
    expect(premiumFor([{ type: "sword", material: "steel", enchantment: 0, cursed: false }])).toBe(115);
  });
  it("newcomer insures a plain amulet -> 60 + 6 + 5 = 71 G", () => {
    expect(premiumFor([{ type: "amulet" }])).toBe(71);
  });
  it("newcomer insures a plain staff -> 80 + 8 + 5 = 93 G", () => {
    expect(premiumFor([{ type: "staff" }])).toBe(93);
  });
  it("newcomer insures a plain potion -> 40 + 4 + 5 = 49 G", () => {
    expect(premiumFor([{ type: "potion" }])).toBe(49);
  });
  it("2 runes -> 50 G base premium -> 50 + 5 + 5 = 60 G", () => {
    expect(premiumFor(times(2, rune))).toBe(60);
  });
  it("3 runes -> 60 G base premium (block) -> 60 + 6 + 5 = 71 G", () => {
    expect(premiumFor(times(3, rune))).toBe(71);
  });
  it("4 runes -> 100 G base premium (no block) -> 100 + 10 + 5 = 115 G", () => {
    expect(premiumFor(times(4, rune))).toBe(115);
  });
  it("7 runes -> 175 G base premium -> 175 + 17.5 + 5 = 197.5 -> 198 G", () => {
    expect(premiumFor(times(7, rune))).toBe(198);
  });
  it("2 runes + 1 moonstone -> 75 G base premium (different types, no block) -> 87.5 -> 88 G", () => {
    expect(premiumFor([...times(2, rune), moonstone])).toBe(88);
  });
  it("3 runes + 3 moonstones -> 120 G base premium (two blocks) -> 120 + 12 + 5 = 137 G", () => {
    expect(premiumFor([...times(3, rune), ...times(3, moonstone)])).toBe(137);
  });
  it("newcomer with a cursed steel sword (enchantment 3) -> 165 G", () => {
    expect(premiumFor([{ type: "sword", material: "steel", enchantment: 3, cursed: true }])).toBe(165);
  });
  it("cursed sword + plain amulet -> 160 base + 50 curse (of the sword only) = 210, + 16 first + 5 fee = 231 G", () => {
    expect(premiumFor([{ type: "sword", cursed: true }, { type: "amulet", cursed: false }])).toBe(231);
  });
  it("sword with exactly enchantment 5 -> high-enchantment surcharge: 100 + 30 + 10 + 5 = 145 G", () => {
    expect(premiumFor([{ type: "sword", enchantment: 5, cursed: false }])).toBe(145);
  });
  it("cursed sword with enchantment 5 -> both surcharges: 100 + 50 + 30 + 10 + 5 = 195 G", () => {
    expect(premiumFor([{ type: "sword", enchantment: 5, cursed: true }])).toBe(195);
  });
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge: 115 G");
  it.todo("cursed sword with enchantment 4 -> only curse surcharge: 165 G");
  it.todo("customer with exactly 2 years -> loyalty discount: 100 - 20 + 10 + 5 = 95 G");
  it.todo("customer with 1 year -> no loyalty discount: 115 G");
  it.todo("second quote of a newcomer -> follow-up discount: first 115 G, second 100 + 10 - 15 + 5 = 100 G");
  it.todo("long-standing customer (3 years), second quote of cursed sword enchantment 7 -> 160 G (first insurance still applies)");
  it.todo("premium yielding 197.5 G (second quote: cursed sword + 2 runes) -> rounded up to 198 G");
});

describe("claim", () => {
  it.todo("regular steel sword enchantment 3, damage 500 -> payout 400, remainingCap 1600");
  it.todo("rune (insurance value 250), damage 200 -> payout 100, remainingCap 400");
  it.todo("amulet (insurance value 600), damage 200 -> payout 100, remainingCap 1100");
  it.todo("staff (insurance value 800), damage 200 -> payout 100, remainingCap 1500");
  it.todo("potion (insurance value 400), damage 200 -> payout 100, remainingCap 700");
  it.todo("moonstone (insurance value 250), damage 200 -> payout 100, remainingCap 400");
  it.todo("steel sword enchantment 9, damage 1000 -> payout 400 (50 % then deductible)");
  it.todo("dragon-material sword enchantment 9, damage 1000 -> payout 400 (50 % rule wins)");
  it.todo("dragon-material sword exactly enchantment 8, damage 1000 -> payout 400");
  it.todo("dragon-material sword enchantment 5, damage 800 -> payout 700 (full reimbursement)");
  it.todo("dragon attack damages sword (500) and amulet (300) -> payout 600 (deductible per item), remainingCap 2600");
  it.todo("policy with two swords, both damaged 500 each -> payout 800, remainingCap 3200 (cap 4000)");
  it.todo("cursed sword policy -> cap 2000 from unmodified insurance value: damage 500 -> payout 400, remainingCap 1600");
  it.todo("sword + 3 runes (block) -> insurance sum 1750, cap 3500: sword damage 500 -> payout 400, remainingCap 3100");
  it.todo("two successive claims of 1500 on a sword -> payout 1400 / remainingCap 600, then payout 600 / remainingCap 0");
  it.todo("payout yielding 350.5 G (steel sword enchantment 9, damage 901) -> rounded down to 350 G");
});
